function pvpSessionSave(){try{localStorage.setItem('sealbeast_pvp_v1',JSON.stringify({endpoint:String(window.SHEET_URL||'').trim(),room:PVP.room?.id||'',token:PVP.token,code:PVP.code,pending:PVP.pending}))}catch(e){}}
