 if(!parry&&!barrier)return false;
 if(parry)t.buffs=t.buffs.filter(x=>x.pas!=='class10_parry');else t.class10Barrier=0;
 class10AttackContexts.at(-1)?.blocked.add(t.id+'|'+u.id);
