const latestCareerPanel=careerPanel;careerPanel=function(cls){
 const base=baseOf(cls),ids=[];const notes=[];
 if(base==='archer')ids.push('archer_boss_evasion');
 if(base==='mage')ids.push('mage_elemental_barrier');
 if(base==='gunner'){humanPas(cls,{},60);ids.push('gunnerBossBounty','gunner_ambush55');}
 if(base==='summoner')ids.push('summoner_soul_exchange');
 if(['stormcaller','demolisher'].includes(cls))ids.push('small_group_area');
 if(base==='druid')notes.push('ร่างแปลงทุกร่างใช้สกิลร่างคนได้ทุกท่า แปลงร่างครั้งแรกต่อการต่อสู้ไม่เสียเทิร์น แต่ยังใช้ MP');
 if(['druid','summoner'].includes(base))notes.push('สกิลฟื้น HP: เล่นคนเดียว ×0.70; PVP จู่โจมค่าย สงครามกิลด์ หอคอย และบอสโลก ×1.00 ไม่ใช่ตัวคูณของการดูดเลือดหรือฟื้นต่อเนื่อง');
 if(base==='thief')notes.push('ร่างเงา: HP 25% และค่าสถานะอื่น 80% ของร่างจริง');
 if(['sealmaster','spiritlord'].includes(cls))notes.push('เฉพาะ PVP เมื่อยังมีคู่หูมีชีวิต: รับดาเมจ ×0.60; คู่หูฝ่ายตรงข้ามโจมตีผู้ผนึกมีตัวคูณ ×0.70 อีกชั้น ก่อนตัวปรับอาชีพ PVP');
 if(SOLO_DEMON_CAREER_DAMAGE[cls])notes.push('เฉพาะศึกจอมมารโหมดคนเดียว: ดาเมจผู้ผนึก ×'+SOLO_DEMON_CAREER_DAMAGE[cls]+' ไม่เพิ่มดาเมจคู่หู');
 const a=PVP_CAREER_BALANCE[cls];if(a){const out=typeof a==='number'?a:a.out||1,pet=typeof a==='number'?a:a.pet||1,inc=typeof a==='number'?1:a.incoming||1;notes.push('ตัวปรับสมดุลเฉพาะ PVP: ดาเมจผู้ผนึก ×'+out+' / คู่หู ×'+pet+' / ดาเมจที่ผู้ผนึกได้รับ ×'+inc+' คูณร่วมกับกติกาอื่น');}
 return latestCareerPanel(cls)+(ids.length?'<div class="card stack"><b>ความสามารถเพิ่มเติมตามเลเวล</b>'+ids.map(id=>'<div><b>'+esc(PAS[id].n)+'</b><p class="sub">'+esc(PAS[id].d)+'</p></div>').join('')+'</div>':'')+notes.map(t=>'<p class="sub">'+esc(t)+'</p>').join('');
};
const latestClassTree=vClassTree;vClassTree=function(){return latestClassTree()+'<details class="card"><summary>กติกาคู่หูและการฟื้นฟูที่ใช้ร่วมกันทุกอาชีพ</summary><p>คู่หูที่ยังมีชีวิตเกิน 1 ตัว: พลังโจมตีกายภาพและเวทของคู่หูทุกตัวลด 15% ต่อตัวที่เกิน (2 ตัวเหลือ 85%, 3 ตัวเหลือ 70%)</p><p>คู่หูโจมตีบอส: ดาเมจ ×0.70; เฉพาะ PVP คู่หูโจมตีผู้ผนึก: ×0.70 และมีการแบ่งพลังฝูงเพิ่มเติม</p><p>สกิลฟื้น HP ของอสูร: ×0.70 ทุกอาชีพ พาสซีฟเพิ่มฮีลและผลเฉพาะการต่อสู้ยังคูณร่วมกัน</p><p>คริติคอลใส่บอส: ดาเมจของฮิตคริติคอล ×0.75 หลังคำนวณคริ</p></details>';};
const latestSkillDescription=skillDesc;skillDesc=function(id){const sk=SK[id];return latestSkillDescription(id)+(id==='class10_parry'?' · '+PAS.class10_parry.d:'')+(sk?.t==='heal'?' · สายดรูอิด/อัญเชิญ: ฮีลเล่นคนเดียว ×0.70 โหมดอื่น ×1.00; อสูรฮีล ×0.70'+(sk.rev||sk.revAll?' · การชุบชีวิตใช้ HP '+sk.pw+'% โดยไม่บวกพลังเวทหรือคูณฮีล':''):'');};
// Additive equipment catalog only: no combat-rule changes. Shared by client and authoritative online API.
function installForestRiddleCraft(){
 for(const [zone,tier,label,element]of [[7,0,'ตราช่างฝึก','grass'],[6,5,'ตราคลังรัตติกาล','dark']])for(const slot of ['weapon','armor','gloves','boots','belt','bracelet','ring','necklace','crown']){
  const types=slot==='weapon'?Object.keys(WT):[null];for(const wt of types){const base=EQ[wt?'wp_'+wt+tier:slot+'_'+tier];if(!base)throw Error('Missing riddle craft base');const id='cf_riddle'+zone+'_'+slot+(wt?'_'+wt:'');EQ[id]={...base,n:(wt?WT[wt].n:SLOTN[slot])+label,lv:zone===7?1:44,price:Math.round(base.price*1.5),st:Object.fromEntries(Object.entries(base.st).map(([k,v])=>[k,Math.max(1,Math.round(v*1.15))])),craft:'riddle'+zone,eventCraft:1,riddleZone:zone,special:1,...(wt?{el:element}:{})};if(['armor','crown'].includes(slot))EQ[id].defTypes=[element];}
 }
}
installForestRiddleCraft();
const forestRiddleGachaPools=gachaPools;gachaPools=function(){const p=forestRiddleGachaPools();for(const k of ['gear','craft','legendGear'])if(p[k])p[k]=p[k].filter(id=>!EQ[id]?.eventCraft);return p;};

const FOREST_RIDDLES=SECRET_DATA.riddles;
const ForestRiddle={
 busy:false,
 session(){return S.zone?.riddleSession;},
 data(){return FOREST_RIDDLES.find(d=>d.id===this.session()?.id);},
 active(){return !!(this.session()||S.zone?.falseBoss);},
 persist(){towerCheckpoint();this.checkpoint();localStorage.setItem(SAVE,JSON.stringify(S));},
 transact(fn){if(this.busy)return;this.busy=true;const before=JSON.stringify(S);try{fn();this.persist();render();this.focus();}catch(e){S=JSON.parse(before);toast('บันทึกเหตุการณ์ไม่ได้ ข้อมูลยังไม่เปลี่ยน ลองอีกครั้ง');}finally{this.busy=false;}},
 focus(){document.getElementById('forestRiddle')?.scrollIntoView?.({block:'start'});},
 plan(z){if(z.riddleRun)return z.riddleRun;const found={reward:Math.random()<.10,hazard:Math.random()<.10},run={};for(const group of ['reward','hazard']){const pool=FOREST_RIDDLES.filter(d=>d.zone===z.id&&d.group===group);run[group]={id:pool.length?pick(pool).id:null,depth:found[group]?5+Math.floor(Math.random()*4):null,offered:false,used:false};}z.riddleRun=run;return run;},
 enter(group){const z=S.zone,p=z&&this.plan(z)[group];if(!p||!p.offered||p.used||!p.id||this.active()||S.battle||z.secretSession||z.specialSession||z.warpGate)return;this.transact(()=>{z.depth++;z.fork=null;p.used=true;z.riddleSession={id:p.id,token:crypto.randomUUID(),answered:false,phase:'question',results:[]};z.ev={type:group==='reward'?'riddleReward':'riddleHazard',msg:''};S.screen='zone';zlog('ก้าวที่ '+z.depth+' · '+this.data().name);});},
 valid(token){return !!this.session()&&this.session().token===token&&S.screen==='zone'&&!S.battle;},
 reward(zone){const keys=Object.keys(CRAFT).filter(k=>CRAFT[k].zi===zone-1),pool=zone===7||zone===6?Object.keys(EQ).filter(k=>EQ[k].eventCraft&&EQ[k].riddleZone===zone):keys.map(k=>CRAFT[k].sl==='weapon'?'cf_'+k+'_'+clsWeapon(S.P.cls):'cf_'+k);const allowed=pool.filter(k=>EQ[k]?.craft&&!EQ[k].legend&&!EQ[k].worldLegend&&(EQ[k].slot!=='weapon'||EQ[k].wt===clsWeapon(S.P.cls)));if(!allowed.length)throw Error('No local crafted reward');const id=pick(allowed);S.P.owned.push(id);if(this.session())this.session().rewardId=id;return 'ได้รับ '+EQ[id].n+' · Lv '+EQ[id].lv+' · อุปกรณ์คราฟประจำป่า 1 ชิ้น';},
 penaltyText(p){return p.kind==='gold'?'เสียเงิน '+Math.round(p.rate*100)+'% ของที่มี (ไม่เป็นหนี้)':p.kind==='item'?'ถูกยึดยาหรือไอเท็มใช้งาน 1 ชิ้น ถ้าไม่มีจะเสียเงิน 10%':p.kind==='clone'?'ต้องสู้กับทีมเงาของตนเอง ไม่มีรางวัลจากทีมเงา หนีไม่ได้ ต้องชนะภายใน 60 รอบ มิฉะนั้นพ่ายแพ้ · แพ้เสียเงินและ EXP ตามกติกาป่าปกติ':p.kind==='death'?'เสียชีวิตและถูกพากลับโรงพยาบาลทันที':p.kind==='pet'?'สูญเสียอสูรที่พกเลเวลต่ำสุด 1 ตัวถาวร ยกเว้นตำนาน (ถ้าไม่มีตัวที่เข้าเงื่อนไข เสียเงิน 10%)':'ติดพิษทั้งผู้ผนึกและอสูรที่พกซึ่งยังมีสติ ต้องรักษาด้วยวิธีที่ถูกต้อง';},
 gold(rate){const n=Math.max(0,Math.floor(Math.max(0,S.P.gold||0)*rate));S.P.gold-=n;return 'เสียเงิน '+fmt(n)+' เหรียญ';},
 fall(message,art,index=0){S.P.hp=Math.max(1,Math.round(pStats().hp*.3));S.ui.riddleOutcome={message,art,index};S.zone=null;S.battle=null;S.ui.confirm=null;VQ.length=0;S.screen='hospital';Sound.fx('lose');},
 punish(p,d){if(p.kind==='gold')return this.gold(p.rate);if(p.kind==='item'){const pool=Object.keys(S.P.items).filter(k=>CON[k]&&S.P.items[k]>0&&!CON[k].rareLoot&&k!=='godSeal');if(!pool.length)return this.gold(.1);const id=pick(pool);S.P.items[id]--;if(!S.P.items[id])delete S.P.items[id];return 'ถูกยึด '+CON[id].n+' 1 ชิ้น';}if(p.kind==='poison'){let n=0;for(const o of [S.P,...carriedPets()])if(o.hp>0){o.ailments={...(o.ailments||{}),poison:Math.max(2,Number(o.ailments?.poison)||0)};n++;}return 'ติดพิษ '+n+' ชีวิต · สถานะยังอยู่หลังเหตุการณ์ ต้องรักษา';}if(p.kind==='pet'){normalizePack();const carried=new Set(S.P.carried),victim=S.P.pets.filter(x=>carried.has(x.uid)&&SP[x.sp]&&!SP[x.sp].legendary&&!SP[x.sp].noseal).sort((a,b)=>a.lv-b.lv||Number(a.uid)-Number(b.uid))[0];if(!victim)return 'อสูรตำนานและอสูรที่พักค่ายปลอดภัย · '+this.gold(.1);const name=petName(victim);S.P.pets=S.P.pets.filter(x=>x.uid!==victim.uid);S.P.carried=S.P.carried.filter(x=>x!==victim.uid);S.P.party=S.P.party.filter(x=>x!==victim.uid);fixParty();return 'สูญเสีย '+name+' Lv '+victim.lv+' จากกระเป๋า 1 ตัว';}if(p.kind==='death'){this.fall('ตอบผิด · '+d.name+' · ชาวบ้านช่วยพากลับโรงพยาบาล ฟื้น HP 30%',d.id,Number(this.session()?.choice||0)+1);return 'เสียชีวิต · กลับโรงพยาบาล';}return '';},
 choose(token,id){const d=this.data(),q=this.session();if(!d||!this.valid(token)||q.answered||!d.choices.some(c=>c.id===id))return;this.transact(()=>{q.answered=true;q.choice=id;q.correct=id===d.answer;q.phase='resolved';if(q.correct){q.results=[d.group==='reward'?this.reward(d.zone):'เลือกทางปลอดภัย พ้นภัยโดยไม่เสียทรัพยากร'];Sound.fx(d.group==='reward'?'chest':'rune');}else if(d.penalty.kind==='clone'){q.results=['ตอบผิด · ทีมเงาเลียนแบบผู้ผนึกและอสูรที่กำลังออกสู้'];this.startMirror();}else q.results=[this.punish(d.penalty,d)];});},
 startMirror(){const q=this.session();if(!q||S.battle)return;const allies=[playerUnit(),...party().filter(p=>p.hp>0).slice(0,clsSum(S.P.cls)).map(petUnit)],enemies=allies.map((u,i)=>({...JSON.parse(JSON.stringify(u)),id:'riddle-shadow-'+i,side:'enemy',kind:u.kind==='player'?'human':'npcpet',name:'เงาของ'+u.name,temporary:false,riddleCopy:true,owner:undefined,gold:i===0?Math.max(0,S.P.gold):0,noSeal:true}));q.phase='combat';startBattle(enemies,'riddleMirror',S.zone.id);S.battle.noFlee=true;q.mirrorCheckpoint=JSON.parse(JSON.stringify(S.battle));},
 checkpoint(){const q=this.session();if(q&&S.battle?.kind==='riddleMirror')q.mirrorCheckpoint=JSON.parse(JSON.stringify(S.battle));},
 resumeMirror(token){const q=this.session();if(!this.valid(token)||q.phase!=='mirrorReady'||!q.mirrorCheckpoint)return;this.transact(()=>{S.battle=JSON.parse(JSON.stringify(q.mirrorCheckpoint));S.screen='battle';q.phase='combat';const b=B(),u=b.cur&&uById(b.cur);if(!b.over){if(u&&u.side==='ally'&&!teamAutoUnit(u))b.menu='main';else battleLater(u?aiAct:advance,300);}});},
 leave(token){const q=this.session(),d=this.data();if(!this.valid(token)||!d||['combat','mirrorReady'].includes(q.phase)||!q.answered&&d.group==='hazard')return;this.transact(()=>{delete S.zone.riddleSession;S.zone.ev=null;newFork();});},
 panel(id,index,label){return '<span class="riddle-panel" role="img" aria-label="'+esc(label)+'" style="'+Secret.artStyle('assets/ui/riddles/'+id+'-v1.webp',index,0,1,4)+';--riddle-art:url(\'assets/ui/riddles/'+id+'-v1.webp\');--riddle-y:'+(index*100/3)+'%"></span>';},
 buttons(id,choices,action,token){return '<div class="riddle-choices">'+choices.map((c,i)=>'<button class="riddle-choice" data-a="'+action+'" data-v="'+esc(token+'|'+c.id)+'">'+this.panel(id,i+1,c.name)+'<strong>'+esc(c.name)+'</strong></button>').join('')+'</div>';},
 view(){const d=this.data(),q=this.session();if(!d||!q)return '';return '<section class="stack forest-riddle" id="forestRiddle"><small>เรื่องราวระหว่างทาง</small><h2>'+esc(d.name)+'</h2>'+this.panel(d.id,q.answered?Number(q.choice)+1:0,d.name)+'<p>'+esc(d.text)+'</p>'+(q.answered?'<div class="card stack" role="status">'+(q.rewardId?itemIcon(q.rewardId,64):'')+q.results.map(s=>'<p>'+esc(s)+'</p>').join('')+'</div>':'<h3>'+esc(d.question)+'</h3>'+this.buttons(d.id,d.choices,'riddleAnswer',q.token))+(q.phase==='mirrorReady'?'<button class="btn danger full" data-a="riddleMirrorResume" data-v="'+q.token+'">กลับไปสู้กับทีมเงาที่ค้างอยู่</button>':'')+Secret.status()+(!['combat','mirrorReady'].includes(q.phase)&&(q.answered||d.group==='reward')?'<button class="btn full" data-a="riddleLeave" data-v="'+q.token+'">'+(q.answered?'เดินป่าต่อ':'ไม่รับคำท้า · เดินป่าต่อ')+'</button>':'')+'</section>';}
};
function forestTrialGate(boss,target,buttons){return '<section class="stack warp-gate"><h2>ประตูบอสต้องห้าม</h2><img class="boss-gate-art" src="assets/ui/boss-gates/gate-'+target+'.webp" alt="ประตูบอส '+esc(ZN[target-1].n)+'"><div class="card stack"><h3>'+esc(boss.n)+' · Lv '+boss.lv+'</h3><p>ม่านพลังพาคุณมาหยุดอยู่หน้าประตูที่ปิดสนิท</p>'+Secret.status()+buttons+'</div></section>';}
const FALSE_BOSS_STONE='จงอ่อนแอในเวลาที่ควรอ่อนแอ จงสู้ในเวลาที่ควรสู้ ความกล้าที่พอดีจะนำไปสู่ทางรอด';
const FalseBoss={
 session(){return S.zone?.falseBoss;},
 eligible(){const z=S.zone;return !!z&&S.P.hp>0&&z.id===6&&!z.fakeBossUsed&&!S.P.falseBossTrial?.completed&&!S.battle&&!z.secretSession&&!z.specialSession&&!z.riddleSession&&!z.warpGate&&!z.falseBoss;},
 token(){const q=this.session();return q?q.id+':'+q.rev:'';},
 valid(token){return !!this.session()&&this.token()===token&&S.screen==='zone'&&!S.battle;},
 enter(){if(!this.eligible())return false;ForestRiddle.transact(()=>{const z=S.zone;z.depth++;z.fork=null;z.fakeBossUsed=true;z.falseBoss={id:crypto.randomUUID(),rev:0,phase:'arrival'};z.ev={type:'warpGate',msg:''};S.P.falseBossTrial={...(S.P.falseBossTrial||{}),attempts:(S.P.falseBossTrial?.attempts||0)+1};S.screen='zone';zlog('กับดักวาร์ป! ถูกพามาหน้าประตูบอสแห่ง'+ZN[5].n);});return true;},
 advance(token){if(!this.valid(token))return;const q=this.session();if(!['arrival','gate','stone'].includes(q.phase))return;ForestRiddle.transact(()=>{if(q.phase==='arrival')q.phase='gate';else if(q.phase==='gate'){q.entryHP=S.P.hp;q.entryMaxHP=pStats().hp;q.entryMP=S.P.mp;q.phase='stone';}else q.phase='lightning';q.rev++;});},
 retreat(token){if(!this.valid(token)||this.session().phase!=='gate')return;this.leave(token);},
 leave(token){if(!this.valid(token)||!['gate','result'].includes(this.session().phase))return;ForestRiddle.transact(()=>{delete S.zone.falseBoss;S.zone.ev=null;newFork();});},
 answer(token,id){if(!this.valid(token))return;const q=this.session(),phase=q.phase,answers={lightning:['tree','pool','stay'],chase:['fight','run','crouch'],escape:['door','circle','stele']},correct={lightning:'tree',chase:'run',escape:'circle'};if(!answers[phase]?.includes(id))return;ForestRiddle.transact(()=>{q.rev++;if(id!==correct[phase]){ForestRiddle.fall('พลาดบททดสอบในห้องเทวรูป · ชาวบ้านช่วยพากลับโรงพยาบาล ฟื้น HP 30%','false-boss-'+(phase==='escape'?'escape':phase),answers[phase].indexOf(id)+1);return;}if(phase==='lightning'){q.phase='chase';return;}if(phase==='chase'){q.phase='escape';return;}const damage=Math.floor(q.entryMaxHP*.5);q.damage=damage;q.phase='result';if(q.entryHP>damage){S.P.hp=Math.max(1,Math.min(pStats().hp,q.entryHP-damage));S.P.mp=Math.min(pStats().mp,q.entryMP);q.results=['สายฟ้าลด HP '+damage+' หน่วย · คุณรอดชีวิต','ได้รับ EXP 3,000 หน่วย',...gainExp(S.P,3000,true)];q.chosen=false;Sound.fx('win');}else{const id='wl_'+clsWeapon(S.P.cls);if(!EQ[id]?.worldLegend||EQ[id].slot!=='weapon')throw Error('No matching solar weapon');if(S.P.falseBossTrial?.completed)throw Error('Trial already rewarded');S.P.owned.push(id);S.P.falseBossTrial={...(S.P.falseBossTrial||{}),completed:true,weapon:id};S.P.hp=pStats().hp;S.P.mp=pStats().mp;q.chosen=true;q.rewardId=id;q.results=['คุณคือผู้ถูกเลือกจากพระเจ้า','พระเจ้าชุบชีวิตคุณกลับมา HP / MP เต็ม','พระเจ้ามอบ '+EQ[id].n+' · อาวุธตำนานสุริยันตรงสาย 1 ชิ้น และจากไป'];Sound.fx('revive');}});},
 view(){const q=this.session(),token=this.token(),p=ForestRiddle.panel.bind(ForestRiddle),button=(label,row)=>'<button class="riddle-choice full" data-a="falseBossNext" data-v="'+token+'">'+p('false-boss-stone',row,label)+'<strong>'+esc(label)+'</strong></button>';if(!q)return '';if(q.phase==='arrival')return '<section class="stack warp-arrival" id="forestRiddle"><div class="secret-portal warp-portal"><div class="secret-arrival-image" style="background-image:url(\'assets/ui/secrets/warp-trap-v1.webp\')"></div><i></i><i></i><h2>กับดักวาร์ป!</h2><p>ม่านพลังฉีกเส้นทางสู่ประตูต้องห้าม</p></div><button class="btn danger full" data-a="falseBossNext" data-v="'+token+'">ตั้งสติ · ดูประตูที่ถูกพามา</button></section>';if(q.phase==='gate')return forestTrialGate({n:'เทวรูปหินยักษ์',lv:75},6,'<button class="btn danger full" data-a="falseBossNext" data-v="'+token+'">ท้าทายบอสที่อยู่หลังประตู</button><button class="btn full" data-a="falseBossRetreat" data-v="'+token+'">ถอยผ่านรอยแยก · กลับทางแยกเดิม</button>');if(q.phase==='stone')return '<section class="stack forest-riddle" id="forestRiddle"><h2>ศิลาในห้องเทวรูป</h2>'+p('false-boss-stone',0,'ห้องเงียบกับศิลาปริศนา')+'<blockquote>'+esc(FALSE_BOSS_STONE)+'</blockquote>'+button('อ่านข้อความจบ · ก้าวเข้าสู่ห้อง',1)+'</section>';if(q.phase==='result')return '<section class="stack forest-riddle '+(q.chosen?'god-chosen':'')+'" id="forestRiddle"><h2>'+(q.chosen?'คุณคือผู้ถูกเลือกจากพระเจ้า':'ความกล้าที่พอดีนำไปสู่ทางรอด')+'</h2>'+p('false-boss-stone',q.chosen?3:0,q.chosen?'พระเจ้ามอบอาวุธสุริยัน':'ประตูเปิดให้ผู้รอดชีวิต')+(q.chosen?p('false-boss-stone',2,'พระเจ้าชุบชีวิตผู้ผนึก'):'')+'<div class="card stack" role="status">'+(q.rewardId?itemIcon(q.rewardId,64):'')+q.results.map(s=>'<p>'+esc(s)+'</p>').join('')+'</div>'+Secret.status()+'<button class="btn pri full" data-a="falseBossLeave" data-v="'+token+'">ออกจากห้องอย่างปลอดภัย</button></section>';const defs={lightning:{title:'สายฟ้าทั่วห้อง',text:'สายฟ้าเวทพุ่งลงรอบตัว ต้นไม้ผนึกทอดกิ่งรอบห้อง บ่อน้ำอยู่ด้านข้าง คุณจะหลบอย่างไร?',names:['หลบใต้ต้นไม้รอบห้อง','ลงบ่อน้ำด้านข้าง','ไม่หนี อยู่ที่เดิม'],ids:['tree','pool','stay']},chase:{title:'เทวรูปยักษ์เริ่มไล่เหยียบ',text:'พื้นสั่นสะเทือน รูปปั้นหินยักษ์ก้าวตามมา จะทำอย่างไร?',names:['ต่อสู้กลับ','วิ่งหนี','หมอบลง'],ids:['fight','run','crouch']},escape:{title:'ปลายทางของความกล้า',text:'เทวรูปยังตามมา ประตูทางเข้า วงเวทกลางห้อง และศิลาท้ายห้องอยู่เบื้องหน้า จะวิ่งไปที่ใด?',names:['วิ่งกลับไปที่ประตู','ไปวงเวทกลางห้อง','ซ่อนหลังศิลาท้ายห้อง'],ids:['door','circle','stele']}},d=defs[q.phase];if(!d)return '';return '<section class="stack forest-riddle" id="forestRiddle"><h2>'+d.title+'</h2>'+p('false-boss-'+q.phase,0,d.title)+'<p>'+d.text+'</p>'+ForestRiddle.buttons('false-boss-'+q.phase,d.ids.map((id,i)=>({id,name:d.names[i]})),'falseBossAnswer',token)+Secret.status()+'</section>';}
};
// Real teleport traps close permanently. The optional false gate is the sole exception.
const riddleWarpGate=SecretWarp.gate;SecretWarp.gate=function(){const g=S.zone?.warpGate;if(!g||g.phase==='arrival')return riddleWarpGate.call(this);return forestTrialGate(g.boss,g.target,'<button class="btn danger full" data-a="warpFight">ท้าทายบอสที่อยู่หลังประตู</button><button class="btn full" data-a="surrender">ยอมแพ้ · กลับโรงพยาบาล</button>');};
SecretWarp.retreat=function(){if(S.zone?.warpGate)toast('รอยแยกปิดแล้ว ต้องสู้กับบอสหรือยอมแพ้เท่านั้น');};
EV.riddleReward={n:'ห้องปริศนาช่างฝีมือ',g:'?',d:'เรื่องราวที่รอการตัดสินใจของคุณ',w:0};
EV.riddleHazard={n:'ทางอันตราย',g:'!',d:'เรื่องราวที่รอการตัดสินใจของคุณ',w:0};
const riddleNewFork=newFork;newFork=function(...args){if(ForestRiddle.active())return;const result=riddleNewFork(...args),z=S.zone;if(!z||!z.fork||z.secretSession||z.specialSession||z.warpGate)return result;const run=ForestRiddle.plan(z),depth=z.depth+1;if(depth>=5&&depth<=8)for(const group of ['reward']){const p=run[group];if(p.used||p.offered||p.depth==null||depth<p.depth)continue;const slots=z.fork.map((d,i)=>['secret','specialEvent','riddleReward','riddleHazard'].includes(d.k)?-1:i).filter(i=>i>=0);if(!slots.length)break;z.fork[slots[z.depth%slots.length]]={k:group==='reward'?'riddleReward':'riddleHazard',h:false};p.offered=true;}save();return result;};
const riddleChooseFork=chooseFork;chooseFork=function(i){if(ForestRiddle.active())return;const door=S.zone?.fork?.[Number(i)];if(!door)return;if(door.k==='riddleReward')return ForestRiddle.enter('reward');const z=S.zone,p=ForestRiddle.plan(z).hazard,depth=z.depth+1;if((door.h||door.k==='mist'||door.k==='riddleHazard')&&!['secret','specialEvent'].includes(door.k)&&!S.battle&&!z.secretSession&&!z.specialSession&&!z.warpGate&&!p.used&&p.id&&(door.k==='riddleHazard'||depth>=5&&depth<=8&&p.depth!=null&&depth>=p.depth)){p.offered=true;return ForestRiddle.enter('hazard');}if(door.h&&FalseBoss.eligible()&&Math.random()<.10)return FalseBoss.enter();return riddleChooseFork(i);};
const riddleZone=vZone;vZone=function(){if(FalseBoss.session())return FalseBoss.view();if(ForestRiddle.session())return ForestRiddle.view();return riddleZone();};
const riddleRoute=routePicture;routePicture=function(k,hidden,...args){if(!hidden&&['riddleReward','riddleHazard'].includes(k)){const group=k==='riddleReward'?'reward':'hazard',d=FOREST_RIDDLES.find(d=>d.id===S.zone?.riddleRun?.[group]?.id);if(d)return ForestRiddle.panel(d.id,0,d.name);}return riddleRoute(k,hidden,...args);};
const riddleContinue=handlers.cont;handlers.cont=function(...args){if(ForestRiddle.active())return;return riddleContinue(...args);};
const riddleBoss=handlers.boss;handlers.boss=function(...args){if(ForestRiddle.active())return;return riddleBoss(...args);};
const riddleOpenChest=handlers.openchest;handlers.openchest=function(...args){if(ForestRiddle.active())return;return riddleOpenChest(...args);};
const riddleGo=go;go=function(screen){if(ForestRiddle.active()&&!['zone','wild','settings','battle'].includes(screen)){toast('จบเหตุการณ์หรือยอมแพ้ก่อนเปลี่ยนหน้า');return;}const result=riddleGo(screen);if(S.screen!=='hospital'&&S.ui.riddleOutcome){delete S.ui.riddleOutcome;save();}return result;};
const riddleSave=save;save=function(){ForestRiddle.checkpoint();return riddleSave();};
const riddleMigrate=migrate;migrate=function(){riddleMigrate();const q=ForestRiddle.session();if(q?.phase==='combat'&&!S.battle&&q.mirrorCheckpoint){q.phase='mirrorReady';S.screen='zone';}};
const riddleNewRound=newRound;newRound=function(...args){const b=B();if(b?.kind==='riddleMirror'&&!b.over&&b.round>=60&&b.enemies.some(e=>e.hp>0)){blog('หมอกเงาปิดล้อมครบ 60 รอบ การท้าทายสิ้นสุด');endBattle('lose');render();return;}return riddleNewRound(...args);};
const riddleEndBattle=endBattle;endBattle=function(...args){const b=B();if(b?.kind!=='riddleMirror')return riddleEndBattle(...args);const flags=b.enemies.map(e=>e.temporary);b.enemies.forEach(e=>e.temporary=true);try{return riddleEndBattle(...args);}finally{b.enemies.forEach((e,i)=>e.temporary=flags[i]);save();}};
const riddleBattleAction=battleAction;battleAction=function(v){const mirror=S.battle?.kind==='riddleMirror',q=ForestRiddle.session();if(mirror&&v==='done'&&S.battle.over?.res==='win'&&q){q.phase='resolved';delete q.mirrorCheckpoint;q.results.push('เอาชนะทีมเงาแล้ว · ไม่มี EXP เงิน หรือไอเท็มเพิ่ม');}return riddleBattleAction(v);};
const riddleHospital=vHospital;vHospital=function(){const q=S.ui.riddleOutcome;return (q?'<div class="card stack riddle-outcome">'+(q.secretId?Secret.panel(Secret.data(q.secretId),q.index,q.message):ForestRiddle.panel(q.art,q.index,q.message))+'<p>'+esc(q.message)+'</p></div>':'')+riddleHospital();};
const riddleVillageEligible=villageGearEligible;villageGearEligible=function(id){return !EQ[id]?.eventCraft&&riddleVillageEligible(id);};
const riddleMusic=uploadedMusicScene;uploadedMusicScene=function(){if(S.screen==='zone'&&FalseBoss.session())return {group:FalseBoss.session().chosen?'bgSuccessMusic':'bgDemonBossRoomMusic',stamp:'false-boss:'+FalseBoss.session().phase};if(S.screen==='zone'&&ForestRiddle.session())return {group:ForestRiddle.data()?.group==='hazard'?'bgSuspenseMusic':'bgPuzzleMusic',stamp:'forest-riddle:'+ForestRiddle.data()?.id};return riddleMusic();};
const splitRiddleAnswer=v=>{const i=v.lastIndexOf('|');return [v.slice(0,i),v.slice(i+1)];};
Object.assign(handlers,{riddleAnswer:v=>ForestRiddle.choose(...splitRiddleAnswer(v)),riddleLeave:v=>ForestRiddle.leave(v),riddleMirrorResume:v=>ForestRiddle.resumeMirror(v),falseBossNext:v=>FalseBoss.advance(v),falseBossRetreat:v=>FalseBoss.retreat(v),falseBossAnswer:v=>FalseBoss.answer(...splitRiddleAnswer(v)),falseBossLeave:v=>FalseBoss.leave(v)});const TALES_DATA=SoulbeastContent.WORLD_TALES();
const TALES_SECRET_LEGACY=JSON.parse(JSON.stringify(SECRET_DATA.locations));
const WorldTales={
 busy:false,
 state(){const root=Secret.state();return root.tales||(root.tales={version:1,serial:0,visits:{},quests:{},effects:[],consequences:{},rumors:[],heard:{},shortClaims:{},ending:null});},
 data(id){return TALES_DATA.quests.find(d=>d.id===id);},
 followText(d,r){return d?.stages?.[r?.progress||0]||d?.scene||'';},
 zoneKey(id){return TALES_DATA.zones[id]||'training';},
 run(){const z=S.zone;if(!z)return null;if(!z.taleRun){const s=this.state();s.serial++;s.visits[z.id]=(s.visits[z.id]||0)+1;for(const r of Object.values(s.quests))if(r.kind==='short'&&r.status==='active'&&r.run!==s.serial)r.status='expired';z.taleRun={serial:s.serial,specialDepth:Math.random()<.10?5+Math.floor(Math.random()*4):null,specialUsed:false};}return z.taleRun;},
 session(){return S.zone?.taleSession;},
 token(){return this.session()?.token;},
 valid(token){return !!this.session()&&token===this.token()&&S.screen==='zone'&&!S.battle;},
 persist(){towerCheckpoint();localStorage.setItem(SAVE,JSON.stringify(S));},
 tx(fn){if(this.busy)return false;this.busy=true;const before=JSON.stringify(S);try{fn();this.persist();render();this.focus();return true;}catch(e){S=JSON.parse(before);toast('บันทึกเรื่องราวไม่ได้ ข้อมูลยังไม่เปลี่ยนแปลง ลองอีกครั้ง');return false;}finally{this.busy=false;}},
 focus(){document.getElementById('worldTales')?.scrollIntoView?.({block:'start'});},
 block(){return !!this.session();},
 panel(zone,row,col,label){const path='assets/ui/tales/'+this.zoneKey(zone)+'-v1.webp';return '<figure class="tale-panel" role="img" aria-label="'+esc(label)+'" style="--tale-art:url(\''+path+'\');'+Secret.artStyle(path,row,col,3,6)+'"></figure>';},
 villager(label='ชาวบ้านข้างทาง'){return '<figure class="tale-panel tale-villager" role="img" aria-label="'+esc(label)+'" style="--tale-art:url(\'assets/ui/tales/roadside-villagers-v2.webp\');--crop-size:100% 100%;--crop-position:0% 0%;--crop-ratio:1.5;--crop-width:1536px"></figure>';},
 cardButton(zone,row,col,label,action,value,disabled=false){return '<button class="btn tale-choice" data-a="'+action+'" data-v="'+esc(value)+'" '+(disabled?'disabled':'')+'>'+this.panel(zone,row,col,label)+'<strong>'+esc(label)+'</strong></button>';},
 follow(){const z=S.zone;if(!z)return null;const run=this.run(),s=this.state();return Object.values(s.quests).filter(r=>r.status==='active'&&(r.kind==='short'?r.run===run.serial&&z.depth+1>=r.nextDepth:r.targets[r.progress]===z.id)).sort((a,b)=>(a.kind==='short'?-1:1)-(b.kind==='short'?-1:1))[0]||null;},
 eligible(){const z=S.zone,run=this.run(),s=this.state();return TALES_DATA.quests.filter(d=>d.zone===z.id&&(!s.quests[d.id]||d.kind==='short'&&s.quests[d.id].status!=='active'&&s.quests[d.id].run!==run.serial)&&(d.kind!=='short'||z.depth<=5)&&Object.values(s.quests).filter(r=>r.status==='active').length<6);},
 encounter(kind='villager'){
  const z=S.zone;if(!z||S.battle||this.session()||z.secretSession||z.specialSession||z.riddleSession||z.falseBoss||z.warpGate)return;
  this.tx(()=>{const follow=kind==='follow'?this.follow():null;const special=kind==='special'?TALES_DATA.special.find(d=>d.zone===z.id):null;let d=null,mode='rumor',text='';
   if(follow){d=this.data(follow.id);mode='follow';}
   else if(special){d=special;mode='special';z.taleRun.specialUsed=true;}
   else if(Math.random()<.5){const pool=this.eligible();if(pool.length){d=pick(pool);mode='offer';}}
   if(mode==='rumor')text=this.rumor();
   z.depth++;z.fork=null;z.ev={type:'worldTale',msg:''};z.taleSession={token:crypto.randomUUID(),mode,id:d?.id||null,text,result:[],followId:follow?.id};S.screen='zone';zlog('ก้าวที่ '+z.depth+' · '+(d?.title||'ผู้เดินทางข้างทาง'));
  });
 },
 accept(token){if(!this.valid(token)||this.session().mode!=='offer')return;this.tx(()=>{const q=this.session(),d=this.data(q.id),s=this.state();const previous=s.quests[d.id],run=this.run();if(previous&&!(d.kind==='short'&&previous.status!=='active'&&previous.run!==run.serial))return;s.quests[d.id]={repeat:previous?.status==='completed'||!!previous?.repeat,id:d.id,kind:d.kind,status:'active',run:run.serial,progress:0,targets:d.targets.slice(),nextDepth:Math.min(9,S.zone.depth+1),acceptedAt:run.serial};q.mode='result';q.result=[d.kind==='short'?'รับปากแล้ว · จุดติดตามจะปรากฏก่อนถึงประตูบอสในรอบนี้':'รับปากแล้ว · ตามรอยที่ '+d.targets.map(i=>ZN[i-1].n).join(' → ')+' · บันทึกข้ามรอบได้'];});},
 next(token){if(!this.valid(token)||this.session().mode!=='follow')return;this.tx(()=>{const q=this.session(),r=this.state().quests[q.followId],d=this.data(r.id);if(!r||r.status!=='active')return;if(r.kind!=='short'&&r.progress<r.targets.length-1){const discovered=this.followText(d,r);r.progress++;q.mode='result';q.result=['พบร่องรอยใหม่: '+discovered,'ผู้เดินทางฝากให้ไปฟังเรื่องอีกด้านที่ '+ZN[r.targets[r.progress]-1].n];}else q.mode='question';});},
 choiceData(){const q=this.session();if(!q)return null;return TALES_DATA.special.find(d=>d.id===q.id)||this.data(q.id||q.followId);},
 costText(e){const a=[];if(e.costItem)a.push('ใช้ '+CON[e.costItem].n+' 1 ชิ้น');if(e.costHP)a.push('ใช้ HP '+Math.round(e.costHP*100)+'% ของ HP เต็ม (ไม่ทำให้หมดสติ)');if(e.costMP)a.push('ใช้ MP '+Math.round(e.costMP*100)+'% ของ MP เต็ม');if(e.battle)a.push('ต้องต่อสู้เพื่อทำตามการตัดสินใจ');return a.join(' · ');},
 canPay(e){return (!e.costItem||(S.P.items[e.costItem]||0)>0)&&(!e.costMP||S.P.mp>=Math.ceil(pStats().mp*e.costMP));},
 request(token,index){if(!this.valid(token)||!['question','special'].includes(this.session().mode))return;const d=this.choiceData(),i=Number(index),a=d?.actions[i];if(!Number.isInteger(i)||!a||!this.canPay(a.effects))return;if(this.session().mode==='special'||d.kind==='long'){S.ui.confirm={msg:'«'+a.label+'»?',act:'taleCommit',v:token+'|'+i};render();}else this.choose(token,i);},
 pay(e,out){if(e.costItem){S.P.items[e.costItem]--;out.push('ใช้ '+CON[e.costItem].n+' 1 ชิ้น');}if(e.costHP){const n=Math.ceil(pStats().hp*e.costHP);S.P.hp=Math.max(1,S.P.hp-n);out.push('ใช้ HP '+n);}if(e.costMP){const n=Math.ceil(pStats().mp*e.costMP);S.P.mp-=n;out.push('ใช้ MP '+n);}},
 choose(token,index){if(!this.valid(token)||!['question','special'].includes(this.session().mode))return;const d=this.choiceData(),i=Number(index),a=d?.actions[i];if(!Number.isInteger(i)||!a||!this.canPay(a.effects))return;this.tx(()=>{const q=this.session();S.ui.confirm=null;this.pay(a.effects,q.result);q.branch=i;const promise=this.state().quests[d.id];if(promise?.kind==='long')promise.lockedBranch=i;q.pending={id:d.id,kind:q.mode==='special'?'special':'quest',index:i};q.mode='resolving';if(a.effects.battle){q.mode='combat';const zd=ZN[S.zone.id-1],sp=pick(zd.sp),lv=clamp(S.P.lv,zd.lv[0],zd.lv[1]),enemy=wildUnit(sp,lv,0);enemy.temporary=true;enemy.noSeal=true;enemy.name='ผู้ขวางทาง · '+enemy.name;startBattle([enemy],'taleTrial',S.zone.id);S.battle.noFlee=true;q.battleCheckpoint=JSON.parse(JSON.stringify(S.battle));}else this.resolve();});},
 resolve(){const q=this.session(),p=q.pending;if(!p)return;const d=p.kind==='special'?TALES_DATA.special.find(d=>d.id===p.id):this.data(p.id),a=d.actions[p.index],s=this.state(),key=p.kind+':'+d.id;if(s.consequences[key]&&!(p.kind==='quest'&&d.kind==='short'&&s.quests[d.id]?.repeat)){q.result.push('คำตัดสินนี้ถูกบันทึกแล้ว ไม่มีรางวัลซ้ำ');}else{q.result.push(a.outcome);q.result.push(...this.effects(a.effects,d.zone,key,d.title));if(p.kind==='quest'){const r=s.quests[d.id];r.status='completed';r.branch=p.index;r.outcome=a.outcome;r.completedAt=s.serial;q.result.push(...this.reward(d));}if(!s.consequences[key])this.record(key,d.zone,d.title,p.index,a.outcome);}delete q.pending;delete q.battleCheckpoint;q.mode='result';},
 reward(d){const out=[],s=this.state();if(s.shortClaims[d.id]===s.serial)return ['เคยรับรางวัลของเรื่องนี้ในรอบนี้แล้ว'];s.shortClaims[d.id]=s.serial;const level=ZN[d.zone-1].lv[0],gold=(d.kind==='short'?35:d.kind==='medium'?100:180)+level*(d.kind==='short'?4:10);const amount=s.quests[d.id]?.repeat?Math.max(1,Math.round(gold*.25)):gold;S.P.gold+=amount;out.push('ได้รับ '+fmt(amount)+' เหรียญ');if(d.kind==='short'){S.P.items.pot=(S.P.items.pot||0)+1;out.push('ได้รับ '+CON.pot.n+' 1 ชิ้น');}else{const pool=Object.keys(EQ).filter(id=>{const e=EQ[id];return (e.craft||e.rare||e.rareLoot)&&!e.legend&&!e.worldLegend&&!e.eventCraft&&!/^(lg|sun|wl_)/.test(id)&&e.lv<=Math.min(S.P.lv,ZN[d.zone-1].lv[1])&&(e.slot!=='weapon'||e.wt===clsWeapon(S.P.cls));});if(pool.length){const id=pick(pool);S.P.owned.push(id);out.push('ได้รับ '+EQ[id].n);}}return out;},
 record(key,zone,title,branch,outcome){const s=this.state();s.consequences[key]={key,zone,title,branch,outcome,at:s.serial};},
 effects(e,zone,source,title){const out=[],s=this.state();if(e.heal){Secret.heal(e.heal,e.heal);out.push('ฟื้น HP/MP '+Math.round(e.heal*100)+'% ให้ผู้ที่ยังมีสติ');}for(const kind of ['seal','price','guard','bossAttack'])if(e[kind]){s.effects=s.effects.filter(x=>!(x.source===source&&x.kind===kind));s.effects.push({source,title,kind,amount:e[kind],zone,element:e.element||null,until:(s.visits[zone]||0)+2});out.push(this.effectText(s.effects[s.effects.length-1]));}if(e.allyBoss&&!s.effects.some(x=>x.source===source&&x.kind==='dragonAid')){s.effects.push({source,title,kind:'dragonAid',amount:-.20,zone:0,once:true,created:s.serial});out.push('ผนึกอุ่นขึ้นเมื่อมังกรบินจากไป');}return out;},
 active(kind){if(!S.P)return [];const s=this.state(),zone=S.zone?.id;return s.effects.filter(e=>e.kind===kind&&(e.zone===0||e.zone===zone)&&(e.once?([5,6].includes(zone)&&s.serial>e.created):e.until>=(s.visits[e.zone]||0)));},
 modifier(kind,element){const list=this.active(kind).filter(e=>!e.element||element?.includes(e.element));return clamp(list.reduce((n,e)=>n+e.amount,0),-.25,.25);},
 effectText(e){const names={seal:'โอกาสผนึก',price:'ราคาซื้อในป่า',guard:'ลดความเสียหายที่ทีมได้รับ',bossAttack:'พลังโจมตีบอสช่วง 2 เทิร์นแรก'};return e.title+' · '+(names[e.kind]||'ร่องรอยคำสัญญา')+' '+(e.amount>0?'+':'')+Math.round(e.amount*100)+'%'+(e.element?' · '+(EL[e.element]?.n||e.element):'')+' · ใน '+ZN[(e.zone||1)-1].n+' · เหลือ '+Math.max(0,e.until-(this.state().visits[e.zone]||0)+1)+' รอบของป่านี้ (รวมรอบปัจจุบัน)';},
 offline(){return !!S.zone&&!!S.battle&&!S.battle.towerRun&&['wild','beast','boss','secret','warpBoss','traveler','bandit','taleTrial','riddleMirror'].includes(S.battle.kind)&&!isWorldBattle();},
 rumor(){const s=this.state();if(s.effects.some(e=>e.kind==='dragonAid')&&!s.heard.dragonWing){s.heard.dragonWing=true;const text='คนเฝ้าค่ายบอกว่าเมื่อคืนมีเงาปีกใหญ่บินผ่าน แต่มันไม่ได้ลงมาโจมตี เหมือนกำลังตามหารอยผนึกที่คุ้นเคย';s.rumors.push({text,at:s.serial});return text;}const all=Object.values(s.consequences),unheard=all.filter(c=>!s.heard[c.key]);if(unheard.length){const c=pick(unheard);s.heard[c.key]=1;const text='ผู้เดินทางจาก'+ZN[c.zone-1].n+'เล่าว่า «'+c.outcome+'» เขาได้ยินจากคนอีกทอด จึงยังไม่แน่ใจว่ารายละเอียดครบหรือไม่';s.rumors.push({text,key:c.key,at:s.serial});s.rumors=s.rumors.slice(-60);return text;}const text=pick(TALES_DATA.chatter);s.rumors.push({text,at:s.serial});s.rumors=s.rumors.slice(-60);return text;},
 leave(token){if(!this.valid(token)||['combat','question','resolving'].includes(this.session().mode))return;this.tx(()=>{delete S.zone.taleSession;S.zone.ev=null;newFork();});},
 resume(){const q=this.session();if(q?.mode==='combat'&&!S.battle){q.mode='resume';q.token=crypto.randomUUID();}},
 resumeBattle(token){if(!this.valid(token)||this.session().mode!=='resume'||!this.session().battleCheckpoint)return;this.tx(()=>{const q=this.session();S.battle=JSON.parse(JSON.stringify(q.battleCheckpoint));S.screen='battle';q.mode='combat';const b=B(),u=b.cur&&uById(b.cur);if(!b.over){if(u&&u.side==='ally'&&!teamAutoUnit(u))b.menu='main';else battleLater(u?aiAct:advance,300);}});},
 view(){const q=this.session();if(!q)return '';const d=this.choiceData()||this.data(q.followId),zone=d?.zone||S.zone.id,row=d?.row||0;let text=q.text||d?.intro||'',body='';
  if(q.mode==='offer')body=this.cardButton(zone,row,1,'รับฟังและช่วยเหลือ','taleAccept',q.token)+this.cardButton(zone,row,2,'ขอเดินทางต่อ','taleLeave',q.token);
  if(q.mode==='follow'){text=this.followText(d,this.state().quests[q.followId||q.id]);body=this.cardButton(zone,row,1,'ฟังเรื่องราวต่อ','taleNext',q.token);}
  if(['question','special'].includes(q.mode)){text=d.scene;body=d.actions.map((a,i)=>this.cardButton(zone,row,i+1,a.label,'taleChoice',q.token+'|'+i,!this.canPay(a.effects))).join('');}
  if(q.mode==='result'){text=q.result.join('\n\n');body='<button class="btn pri full" data-a="taleLeave" data-v="'+q.token+'">เดินทางต่อ</button>';}
  if(q.mode==='rumor')body='<button class="btn full" data-a="taleLeave" data-v="'+q.token+'">ขอบคุณสำหรับเรื่องเล่า</button>';
  if(q.mode==='resume'){text='การคุ้มกันยังไม่จบ กลับเข้าสู่การต่อสู้ที่บันทึกไว้';body='<button class="btn pri full" data-a="taleResume" data-v="'+q.token+'">กลับไปช่วยผู้เดินทาง</button>';}
  return '<section class="stack" id="worldTales"><small>เรื่องเล่าจากผู้เดินทาง</small><h2>'+esc(d?.title||'ชาวบ้านข้างทาง')+'</h2>'+(q.mode==='rumor'?this.villager():this.panel(zone,row,q.mode==='result'?Math.min(2,(q.branch||0)+1):0,d?.title||'ผู้เดินทาง'))+'<p role="status">'+esc(text)+'</p><div class="tale-choices">'+body+'</div>'+Secret.status()+'</section>';
 },
 epilogues(snapshot){const s=this.state(),cs=[...(snapshot||Object.values(s.consequences))];for(const d of SECRET_DATA.locations){const old=Secret.state().locations[d.id];if(old?.completed&&!s.consequences['secret:'+d.zone])cs.push({key:'legacy:'+d.id,zone:d.zone,title:d.name,branch:null,outcome:old.outcome||d.evidence});}return [7,1,2,3,4,5,6].map(zone=>{const list=cs.filter(c=>c.zone===zone);const major=list.filter(c=>c.key.startsWith('secret:')||c.key.startsWith('legacy:')||this.data(c.key.slice(6))?.kind==='long');let text=list.length?(major.length?major:list).slice(0,2).map(c=>c.outcome).join(' '):'ผู้คนยังเดินทางต่อในดินแดนที่คุณไม่ได้ฝากคำตัดสินไว้ เรื่องราวของพวกเขายังไม่สิ้นสุด';if(zone===4){const a=list.find(c=>c.key==='secret:4'),b=list.find(c=>c.key==='special:encounter-4');if(a?.branch===0&&b?.branch===1)text+=' มังกรที่มีรอยแผลเดิมมาพบคุณเพียงตัวเดียว ก่อนบินกลับไปหาฝูงที่ยังไม่ไว้ใจมนุษย์';}const longs=list.filter(c=>c.key.startsWith('quest:')&&this.data(c.key.slice(6))?.kind==='long');if(longs.length)text+=' สิ่งที่ผู้เดินทางร่วมสร้างยังคงอยู่ แม้สงครามจบลงแล้ว';return {zone,title:ZN[zone-1].n,text};});},
 journal(){const s=this.state(),rs=Object.values(s.quests);return '<section class="stack" id="worldTales"><h2>สมุดผู้เดินทางและข่าวลือ</h2><p>ข่าวลือเป็นคำบอกเล่า ส่วนคำตัดสินที่บันทึกแล้วเปลี่ยนย้อนหลังไม่ได้</p>'+rs.map(r=>{const d=this.data(r.id);return '<details class="card"><summary>'+esc(d.title)+' · '+({active:'กำลังติดตาม',completed:'จบเรื่องแล้ว',expired:'คลาดกันในป่ารอบก่อน',failed:'การช่วยเหลือไม่สำเร็จ'}[r.status]||r.status)+'</summary>'+this.panel(d.zone,d.row,0,d.title)+'<p>'+esc(d.intro)+'</p><p>'+esc(r.outcome||(r.kind==='short'?'ติดตามจุดนัดหมายในป่ารอบนี้':'ไปยัง '+ZN[r.targets[r.progress]-1].n))+'</p></details>';}).join('')+'<h3>ผลของคำตัดสิน</h3>'+s.effects.filter(e=>e.kind!=='dragonAid'&&e.until>=(s.visits[e.zone]||0)).map(e=>'<p class="card">'+esc(this.effectText(e))+'</p>').join('')+'<h3>ข่าวที่เคยได้ยิน</h3>'+s.rumors.slice().reverse().map(r=>'<p class="card">'+esc(r.text)+'</p>').join('')+(S.P.cleared?'<h3>โลกหลังชัยชนะ</h3>'+this.epilogues(s.ending?.choices).map(e=>'<details class="card"><summary>'+esc(e.title)+'</summary>'+this.panel(e.zone,5,0,e.title)+'<p>'+esc(e.text)+'</p></details>').join(''):'')+'<button class="btn full" data-a="taleBookBack">กลับ</button></section>';}
};

// New paths are visible on either side; existing hidden routes and unique events are preserved.
EV.villager={n:'ชาวบ้านข้างทาง',g:'♧',d:'คนเดินทางหยุดพักอยู่ข้างทาง',w:0};
EV.taleFollow={n:'รอยนัดหมายของผู้เดินทาง',g:'♧',d:'ติดตามเรื่องที่รับปากไว้',w:0};
EV.taleEvent={n:'ร่องรอยเรื่องราว',g:'♧',d:'พบผู้คนและอสูรที่กำลังตัดสินใจ',w:0};
const talesNewFork=newFork;
newFork=function(...args){if(WorldTales.block())return;const out=talesNewFork(...args),z=S.zone;if(!z||!z.fork)return out;const run=WorldTales.run();if(z.secretSession||z.specialSession||z.riddleSession||z.warpGate)return out;const slots=z.fork.map((d,i)=>!d.h&&!['secret','specialEvent','riddleReward','riddleHazard'].includes(d.k)?i:-1).filter(i=>i>=0);if(!slots.length)return out;const follow=WorldTales.follow(),special=TALES_DATA.special.find(d=>d.zone===z.id),done=special&&WorldTales.state().consequences['special:'+special.id];const k=follow?'taleFollow':!done&&!run.specialUsed&&run.specialDepth!=null&&z.depth+1>=run.specialDepth&&z.depth+1<=8?'taleEvent':Math.random()<.15?'villager':null;if(k)z.fork[pick(slots)]={k,h:false};return out;};
const talesChooseFork=chooseFork;
chooseFork=function(i){if(WorldTales.block())return;const k=S.zone?.fork?.[Number(i)]?.k;if(['villager','taleFollow','taleEvent'].includes(k))return WorldTales.encounter(k==='taleFollow'?'follow':k==='taleEvent'?'special':'villager');return talesChooseFork(i);};
const talesRoute=routePicture;
routePicture=function(k,h,...args){if(!h&&['villager','taleFollow','taleEvent'].includes(k)){const d=k==='taleFollow'?WorldTales.data(WorldTales.follow()?.id):k==='taleEvent'?TALES_DATA.special.find(d=>d.zone===S.zone?.id):null;return k==='villager'?WorldTales.villager():WorldTales.panel(S.zone?.id,d?.row||0,0,d?.title||'ชาวบ้านข้างทาง');}return talesRoute(k,h,...args);};
const talesZone=vZone;
vZone=function(){WorldTales.resume();return WorldTales.session()?WorldTales.view():talesZone();};
Object.assign(handlers,{taleAccept:v=>WorldTales.accept(v),taleNext:v=>WorldTales.next(v),taleLeave:v=>WorldTales.leave(v),taleChoice:v=>{const [t,i]=v.split('|');WorldTales.request(t,i);},taleCommit:v=>{const [t,i]=v.split('|');WorldTales.choose(t,i);},taleResume:v=>WorldTales.resumeBattle(v),taleBook:()=>{if(!S.P||S.battle&&!S.battle.over)return;S.ui.taleReturn=S.screen;S.ui.taleBook=true;S.screen='story';render();},taleBookBack:()=>{const back=S.ui.taleReturn;delete S.ui.taleBook;S.screen=back==='story'?(S.zone?'zone':'town'):back||'town';render();}});
for(const key of ['cont','boss','exitzone','dozone']){const old=handlers[key];handlers[key]=function(...a){if(WorldTales.block())return toast('จบเรื่องที่กำลังฟัง ก่อนเดินทางต่อ');return old(...a);};}
const talesGo=go;
go=function(s){if(WorldTales.block()&&!['zone','wild','settings','battle','story'].includes(s))return toast('จบเรื่องที่กำลังฟัง ก่อนเปลี่ยนหน้า');return talesGo(s);};
const talesStory=vStory;
vStory=function(){return S.ui.taleBook?WorldTales.journal():talesStory()+(S.ui.cinema?'':'<button class="btn full" data-a="taleBook">สมุดผู้เดินทาง · เควสและข่าวลือ</button>');};
const talesBag=vBag;
vBag=function(){return talesBag()+'<button class="btn full" data-a="taleBook">เควส ข่าวลือ และผลของคำตัดสิน</button>';};

// Story effects operate only on offline forest combat and never change species/player baseline stats.
const talesSealChance=sealChance;
sealChance=function(e,pow){const base=talesSealChance(e,pow);if(pow===Infinity||!WorldTales.offline()||e.noSeal||e.temporary||B()?.kind==='taleTrial')return e.noSeal||B()?.kind==='taleTrial'?0:base;return clamp(base*(1+WorldTales.modifier('seal',e.types||[])),0,.97);};
const talesHurt=hurt;
hurt=function(u,d,...args){if(WorldTales.offline()&&u.side==='ally')d=Math.round(d*(1-WorldTales.modifier('guard')));return talesHurt(u,d,...args);};
const talesStartBattle=startBattle;
startBattle=function(es,kind,meta,...args){let aid=null;if(S.zone&&['boss','warpBoss'].includes(kind)){aid=kind==='boss'&&WorldTales.active('dragonAid')[0];const rate=clamp(WorldTales.modifier('bossAttack')+(aid?-.20:0),-.25,.25);for(const u of es.filter(u=>u.boss))if(rate)u.buffs.push({st:'patk',amt:rate,tn:2},{st:'matk',amt:rate,tn:2});if(aid)WorldTales.state().effects=WorldTales.state().effects.filter(e=>e!==aid);}const out=talesStartBattle(es,kind,meta,...args);if(aid)blog('มังกรที่มีรอยแผลเดิมบินผ่านสนาม พลังบอสลดลงชั่วคราวตามคำสัญญา');return out;};
const talesEndBattle=endBattle;
endBattle=function(res){const b=B(),q=WorldTales.session();if(b?.kind==='taleTrial'){if(b.over)return;syncBack();if(res==='win'){WorldTales.resolve();b.over={res,title:'ผ่านเหตุการณ์คุ้มกัน',lines:q.result.slice()};}else{const r=WorldTales.state().quests[q?.id];if(r)r.status=r.kind==='short'?'failed':'active';S.P.hp=Math.max(1,Math.round(pStats().hp*.3));b.over={res:'lose',title:'การช่วยเหลือต้องหยุดลง',lines:['ผู้บาดเจ็บช่วยพาคุณกลับโรงพยาบาล · ไม่เสียเงินหรือ EXP จากการคุ้มกัน','เควสระยะกลางและยาวยังตามต่อได้ในรอบใหม่']};}b.menu='end';save();return;}const out=talesEndBattle(res);if(res==='win'&&b?.kind==='boss'&&Number(b.meta)===6&&S.P.cleared){WorldTales.state().ending={at:Date.now(),choices:JSON.parse(JSON.stringify(Object.values(WorldTales.state().consequences)))};save();}return out;};
const talesBattleAction=battleAction;
battleAction=function(v){const b=B(),q=WorldTales.session();if(b?.kind==='taleTrial'&&q&&b.over&&v==='done'){const won=b.over.res==='win';S.battle=null;if(won){q.mode='result';S.screen='zone';}else{S.zone=null;S.screen='hospital';}save();render();return;}return talesBattleAction(v);};
const talesSave=save;
save=function(){const q=WorldTales.session();if(q&&S.battle?.kind==='taleTrial')q.battleCheckpoint=JSON.parse(JSON.stringify(S.battle));return talesSave();};
const talesFrames=storyFrames;
storyFrames=function(chapter,after){const frames=talesFrames(chapter,after);if(chapter!==6||!after||!S.P?.cleared)return frames;return [...frames,...WorldTales.epilogues(WorldTales.state().ending?.choices).map((e,i)=>{const sceneKey='tale-ending-'+i;CINEMA_ART[sceneKey]='assets/ui/tales/'+WorldTales.zoneKey(e.zone)+'-v1.webp';return {title:e.title,text:e.text,sceneKey,art:6,music:'pianoMusic',taleZone:e.zone};})];};
const talesCinema=cinemaView;
cinemaView=function(intro=false){const html=talesCinema(intro),q=S.ui.cinema,f=q&&storyFrames(q.chapter,q.after)[q.index];return f?.taleZone?html.replace(/<img class="cinema-art"[^>]*>/,WorldTales.panel(f.taleZone,5,0,f.title)):html;};

// Keep the established secret reward pools; replace only the decision narrative and consequences.
for(const spec of TALES_DATA.secrets){const d=SECRET_DATA.locations.find(d=>d.zone===spec.zone);if(!d)continue;d.decision=spec.scene;d.choices.forEach((c,i)=>{const a=spec.actions[i];if(!a)return;c.name=a.label;c.detail=WorldTales.costText(a.effects);c.outcome=a.outcome;c.effects=c.effects.filter(e=>['questPet','questWeapon','trainingPet','trainingWeapon'].includes(e.type));c.effects.push({type:'worldTale',zone:spec.zone,branch:i});});}
const talesSecretEffects=Secret.effects;
Secret.effects=function(list){const out=talesSecretEffects.call(this,list.filter(e=>e.type!=='worldTale'));for(const e of list.filter(e=>e.type==='worldTale')){const d=TALES_DATA.secrets.find(d=>d.zone===e.zone),a=d.actions[e.branch];if(!WorldTales.canPay(a.effects))throw Error('Not enough resources');WorldTales.pay(a.effects,out);out.push(...WorldTales.effects(a.effects,e.zone,'secret:'+e.zone,d.title));WorldTales.record('secret:'+e.zone,e.zone,d.title,e.branch,a.outcome);}return out;};
const talesSecretAllowed=Secret.allowed;
Secret.allowed=function(c){const e=c.effects?.find(e=>e.type==='worldTale');return talesSecretAllowed.call(this,c)&&(!e||WorldTales.canPay(TALES_DATA.secrets.find(d=>d.zone===e.zone).actions[e.branch].effects));};
const talesSecretImage=Secret.imageButton;
Secret.imageButton=function(d,index,label,act,value,detail=''){if(act==='secretChoose'){const i=d.choices.findIndex(c=>c.id===value.split('|')[1]);return '<button class="btn tale-choice" data-a="'+act+'" data-v="'+esc(value)+'" '+(!this.allowed(d.choices[i])?'disabled':'')+'>'+WorldTales.panel(d.zone,5,i+1,label)+'<strong>'+esc(label)+'</strong></button>';}return talesSecretImage.call(this,d,index,label,act,value,detail);};
const talesSecretPanel=Secret.panel;
Secret.panel=function(d,index,label,cls){if(index===0&&!d.tutorial)return WorldTales.panel(d.zone,5,0,label);return talesSecretPanel.call(this,d,index,label,cls);};
const talesSecretChoose=Secret.choose;
Secret.choose=function(token,id){if(!this.valid(token)||!this.allowed(this.location()?.choices.find(c=>c.id===id)||{}))return;return talesSecretChoose.call(this,token,id);};
const talesSecretView=Secret.view;
Secret.view=function(){return talesSecretView.call(this).replace('คำสัญญาถูกบันทึกถาวร · ภาระที่ติดค้างชดเชยได้ในบันทึก','คำเตือน: คำตัดสินนี้เปลี่ยนย้อนหลังไม่ได้ ผลบางอย่างอาจกลับมาในภายหลัง แต่ไม่ปิดกั้นเนื้อเรื่องหลัก');};
const talesSecretBook=Secret.book;
Secret.book=function(){let html=talesSecretBook.call(this);for(const d of SECRET_DATA.locations){const rec=this.state().locations[d.id];if(rec?.completed&&!WorldTales.state().consequences['secret:'+d.zone]){const old=TALES_SECRET_LEGACY.find(x=>x.id===d.id)?.choices.find(c=>c.id===rec.choices.main),now=d.choices.find(c=>c.id===rec.choices.main);if(old&&now)html=html.replace('คำสัญญา: '+esc(now.name),'คำสัญญา: '+esc(old.name));}}return html;};
const talesSecretEnding=Secret.canEnding;
Secret.canEnding=function(){const s=WorldTales.state();return talesSecretEnding.call(this)||(S.P.cleared>0&&Object.values(s.quests).filter(r=>r.kind==='long'&&r.status==='completed').length>=2&&SECRET_DATA.locations.filter(d=>Secret.state().locations[d.id]?.completed).length>=3);};const TALE_EFFECT_KINDS=['seal','price','guard','bossAttack','maxMP','mpCost','potionHP','potionMP','trap','hospital','petXP','bossGuard','elementGuard','encounter'];
const TALE_EFFECT_NAMES={seal:'โอกาสผนึก',price:'ราคาซื้อในป่า',guard:'ลดความเสียหายทีม',bossAttack:'โจมตีบอส 2 เทิร์นแรก',maxMP:'MP สูงสุดผู้ผนึก',mpCost:'MP ที่ใช้ร่ายสกิล',potionHP:'ประสิทธิภาพยาฟื้น HP',potionMP:'ประสิทธิภาพยาฟื้น MP',trap:'ความเสียหายกับดัก',hospital:'ค่ารักษาโรงพยาบาล',petXP:'EXP อสูรจากการต่อสู้ป่า',bossGuard:'ลดความเสียหายจากบอส',elementGuard:'ลดความเสียหายจากธาตุ',encounter:'โอกาสเกิดการต่อสู้ทั่วไป'};
const TALE_RUNTIME={attacker:null,element:null,pendingProtector:false};
const detailState=WorldTales.state;
WorldTales.state=function(){const s=detailState.call(this);s.aftermaths||={};s.followupsSeen||={};return s;};
const detailData=WorldTales.data;
WorldTales.data=function(id){if(String(id).startsWith('after:')){const key=String(id).slice(6),a=this.state().aftermaths[key],d=a&&this.afterDef(a);return d&&{...d,id,row:4,kind:'aftermath'};}return detailData.call(this,id);};
WorldTales.negative=function(e){return ['seal','guard','maxMP','potionHP','potionMP','petXP','bossGuard','elementGuard'].includes(e.kind)?e.amount<0:['price','mpCost','trap','hospital','bossAttack','encounter'].includes(e.kind)&&e.amount>0;};
WorldTales.effects=function(e,zone,source,title){const s=this.state(),out=[];if(e.heal){Secret.heal(e.heal,e.heal);out.push('ฟื้น HP/MP '+Math.round(e.heal*100)+'% ให้ผู้ที่ยังมีสติ');}const items={...(e.items||{})};if(e.item)items[e.item]=(items[e.item]||0)+1;for(const [id,n]of Object.entries(items))if(CON[id]){S.P.items[id]=(S.P.items[id]||0)+n;out.push('ได้รับ '+CON[id].n+' ×'+n);}
 for(const kind of TALE_EFFECT_KINDS)if(e[kind]){s.effects=s.effects.filter(x=>!(x.source===source&&x.kind===kind));const charge=kind==='hospital'&&e.charges,repairBound=kind==='seal'&&e.repairBound,scope=charge||e.globalForest?0:zone;const x={source,title,kind,amount:e[kind],zone:scope,homeZone:zone,element:['seal','elementGuard'].includes(kind)?e.element||null:null};if(charge)x.charges=e.charges;else if(repairBound)x.repairBound=true;else if(e.globalForest)x.expiresSerial=s.serial+Math.max(1,e.duration||3)-1;else x.until=(s.visits[zone]||0)+Math.max(1,e.duration||3)-1;s.effects.push(x);out.push(this.effectText(x));}
 for(const [flag,kind]of [['allyBoss','dragonAid'],['protectorAid','protectorAid']])if(e[flag]&&!s.effects.some(x=>x.source===source&&x.kind===kind)){s.effects.push({source,title,kind,amount:flag==='allyBoss'?-.20:.15,zone:0,once:true,created:s.serial});out.push('คำสัญญาถูกจดจำไว้ในผนึก');}S.P.mp=Math.min(S.P.mp,pStats().mp);return out;};
WorldTales.active=function(kind){if(!S.P)return [];const s=this.state(),zone=S.zone?.id;return s.effects.filter(e=>e.kind===kind&&(e.zone===0||e.zone===zone)&&(e.charges!=null?e.charges>0:e.once?[5,6].includes(zone)&&s.serial>e.created:e.repairBound?!s.aftermaths[e.source]?.repaired:e.expiresSerial!=null?s.serial<=e.expiresSerial:e.until>=(s.visits[e.zone]||0)));};
WorldTales.modifier=function(kind,elements){return clamp(this.active(kind).filter(e=>!e.element||elements?.includes(e.element)).reduce((n,e)=>n+e.amount,0),-.25,.25);};
WorldTales.effectText=function(e){const s=this.state(),name=TALE_EFFECT_NAMES[e.kind]||'ความช่วยเหลือที่ยังมาไม่ถึง',duration=e.charges!=null?'ใช้ได้อีก '+e.charges+' ครั้ง':e.once?'รอศึกเนื้อเรื่องในด่านถัดไป':e.repairBound?'จนกว่าจะช่วยแก้ผลกระทบ (มีเควสตามข่าวในสมุด)':e.expiresSerial!=null?'เหลือ '+Math.max(0,e.expiresSerial-s.serial+1)+' รอบเข้าป่า (รวมรอบปัจจุบัน)':'เหลือ '+Math.max(0,e.until-(s.visits[e.zone]||0)+1)+' รอบของป่านี้ (รวมรอบปัจจุบัน)';return e.title+' · '+name+' '+(e.amount>0?'+':'')+Math.round(e.amount*100)+'%'+(e.element?' · '+(EL[e.element]?.n||e.element):'')+' · '+(e.zone?ZN[e.zone-1].n:'ทุกพื้นที่ที่เข้าเงื่อนไข')+' · '+duration;};
WorldTales.allowedAction=function(a){if(!a||!this.canPay(a.effects))return false;const s=this.state();const q=this.session(),r=q&&s.quests[q.id];if(r?.lockedBranch!=null&&this.data(q.id)?.actions.indexOf(a)!==r.lockedBranch)return false;return (a.requires||[]).every(c=>c.quest?s.quests[c.quest]?.status==='completed':c.afterZone?Object.values(s.aftermaths).some(x=>x.zone===c.afterZone&&x.repaired):c.completed?Object.values(s.quests).filter(x=>x.status==='completed').length>=c.completed:c.longCompleted?Object.values(s.quests).filter(x=>x.kind==='long'&&x.status==='completed').length>=c.longCompleted:c.secretCompleted?SECRET_DATA.locations.filter(d=>Secret.state().locations[d.id]?.completed).length>=c.secretCompleted:false);};
WorldTales.requirementText=function(a){return (a.requires||[]).map(c=>c.quest?'จบเรื่อง '+this.data(c.quest).title:c.afterZone?'ช่วยแก้ผลกระทบใน '+ZN[c.afterZone-1].n:c.completed?'ช่วยผู้เดินทางสำเร็จ '+c.completed+' เรื่อง':c.longCompleted?'จบเควสยาว '+c.longCompleted+' เรื่อง':'สำรวจสถานที่ลับจบ '+c.secretCompleted+' แห่ง').join(' · ');};
WorldTales.healingPotion=function(){return Object.keys(CON).filter(k=>CON[k].hp>0&&!CON[k].rev&&!CON[k].revAll&&(S.P.items[k]||0)>0).sort((a,b)=>CON[a].hp-CON[b].hp)[0]||null;};
WorldTales.donatable=function(){return S.P.owned.map((id,index)=>({id,index})).filter(x=>EQ[x.id]&&!EQ[x.id].legend&&!EQ[x.id].worldLegend&&!/^(sun|wl_|lg)/.test(x.id)&&!Object.values(S.P.eq).includes(x.id));};
const detailCanPay=WorldTales.canPay;
WorldTales.canPay=function(e){return detailCanPay.call(this,e)&&(!e.costGold||S.P.gold>=e.costGold)&&(!e.costPotion||this.healingPotion())&&(!e.costGear||this.donatable().length>0);};
const detailCostText=WorldTales.costText;
WorldTales.costText=function(e){return [detailCostText.call(this,e),e.costGold?'จ่าย '+fmt(e.costGold)+' เหรียญ':'',e.costPotion?'ใช้ '+(this.healingPotion()?CON[this.healingPotion()].n:'ยาฟื้น HP')+' 1 ขวด':'',e.costGear?'สละอุปกรณ์ที่ไม่ได้สวมใส่ 1 ชิ้น (เลือกชิ้นที่จะสละก่อนยืนยัน; ไม่รวมตำนาน)':''].filter(Boolean).join(' · ');};
const detailPay=WorldTales.pay;
WorldTales.pay=function(e,out){if(e.costPotion){const id=this.healingPotion();if(!id)throw Error('No healing potion');S.P.items[id]--;out.push('ใช้ '+CON[id].n+' 1 ขวด');}if(e.costGold){if(S.P.gold<e.costGold)throw Error('not enough gold');S.P.gold-=e.costGold;out.push('จ่าย '+fmt(e.costGold)+' เหรียญ');}if(e.costGear){const x=this.session()?.gearChoice;if(!x||!this.donatable().some(y=>y.index===x.index&&y.id===x.id))throw Error('Choose equipment first');S.P.owned.splice(x.index,1);out.push('สละ '+EQ[x.id].n);}return detailPay.call(this,e,out);};
const detailRequest=WorldTales.request;
WorldTales.request=function(t,i){if(!this.valid(t))return;const a=this.choiceData()?.actions[Number(i)];if(!this.allowedAction(a))return;if(a.effects.costGear&&!this.session().gearChoice){this.session().gearMenu=Number(i);render();return;}if(a.effects.costGear){S.ui.confirm={msg:'«'+a.label+'» · '+EQ[this.session().gearChoice.id].n+'?',act:'taleCommit',v:t+'|'+i};render();return;}return detailRequest.call(this,t,i);};
const detailChoose=WorldTales.choose;
WorldTales.choose=function(t,i){if(!this.valid(t)||!this.allowedAction(this.choiceData()?.actions[Number(i)]))return;const r=this.state().quests[this.session().id],a=this.choiceData().actions[Number(i)];if(r?.kind==='long'&&r.lockedBranch!=null&&r.lockedBranch!==Number(i))return;return detailChoose.call(this,t,i);};
const detailCard=WorldTales.cardButton;
WorldTales.cardButton=function(z,row,col,label,act,v,disabled){const a=act==='taleChoice'?this.choiceData()?.actions[Number(v.split('|')[1])]:null;let html=detailCard.call(this,z,row,Math.min(col,2),label,act,v,disabled||(a&&!this.allowedAction(a)));if(col>2)html=html.replace(this.panel(z,row,2,label),this.extraPanel(z,0,label));const req=a&&this.requirementText(a);return html+(req?'<small>'+esc(req)+'</small>':'');};
WorldTales.extraPanel=function(z,col,label){const row=[7,1,2,3,4,5,6].indexOf(Number(z)),xs=[[2,262],[274,266],[552,267]],ys=[[2,246],[255,246],[509,248],[769,257],[1038,260],[1309,271],[1593,320]],[x,w]=xs[col],[y,h]=ys[row];return '<figure class="tale-extra" role="img" aria-label="'+esc(label)+'" style="--tx:'+(x/(821-w)*100)+'%;--ty:'+(y/(1916-h)*100)+'%;--sx:'+(821/w*100)+'%;--sy:'+(1916/h*100)+'%;--extra-ratio:'+w/h+'"></figure>';};
const detailRecord=WorldTales.record;
WorldTales.record=function(key,zone,title,branch,outcome){detailRecord.call(this,key,zone,title,branch,outcome);const s=this.state(),quest=key.startsWith('quest:')&&this.data(key.slice(6));if(quest?.kind==='short')return;if(!s.aftermaths[key])s.aftermaths[key]={source:key,zone,title,branch,at:s.serial,stage:0,heard:0,repaired:false,availableAfter:s.serial+1};};
const detailFollow=WorldTales.follow;
WorldTales.follow=function(){const z=S.zone,s=this.state();if(!z)return null;const run=this.run(),base=Object.values(s.quests).filter(r=>r.status==='active'&&!(r.deferredUntil>s.serial)&&(r.kind==='short'?r.run===run.serial&&z.depth+1>=r.nextDepth:r.targets[r.progress]===z.id)).sort((a,b)=>(a.kind==='short'?-1:1)-(b.kind==='short'?-1:1))[0];if(base)return base;const a=Object.values(s.aftermaths).filter(a=>!a.repaired&&a.zone===z.id&&a.heard>=1&&s.serial>=a.availableAfter).sort((a,b)=>a.at-b.at)[0];return a?{id:'after:'+a.source,source:a.source,kind:'aftermath'}:null;};
WorldTales.startAfter=function(source,consumeDepth=true){const z=S.zone,s=this.state(),a=s.aftermaths[source];if(!z||!a||a.repaired||z.id!==a.zone||S.battle||this.session())return;this.tx(()=>{if(consumeDepth)z.depth++;z.fork=null;z.ev={type:'worldTale'};z.taleSession={mode:'aftermath',id:'after:'+source,source,token:crypto.randomUUID(),result:[]};a.stage=1;S.screen='zone';});};
const detailEncounter=WorldTales.encounter;
WorldTales.encounter=function(kind){const f=kind==='follow'&&this.follow();if(f?.kind==='aftermath')return this.startAfter(f.source);return detailEncounter.call(this,kind);};
WorldTales.helpAfter=function(token,method){if(!this.valid(token)||this.session().mode!=='aftermath'||!['fund','volunteer','later'].includes(method))return;const a=this.state().aftermaths[this.session().source],def=this.afterDef(a),cost=60+ZN[a.zone-1].lv[0]*8;if(method==='fund'&&S.P.gold<cost)return;if(method==='volunteer'&&S.P.mp<Math.ceil(pStats().mp*.15))return;this.tx(()=>{const q=this.session();if(method==='later'){a.availableAfter=this.state().serial+1;q.mode='result';q.result=['คุณรับฟังและขอตามเรื่องในภายหลัง ผู้ได้รับผลกระทบยังอยู่ในสมุดผู้เดินทาง'];return;}q.pending={kind:'aftermath',source:a.source,method};if(method==='fund'){S.P.gold-=cost;q.result.push('จ่าย '+fmt(cost)+' เหรียญให้ช่างและผู้ดูแล');this.finishAfter();}else{S.P.mp-=Math.ceil(pStats().mp*.15);q.result.push('ใช้แรงช่วยเหลือ · MP 15%');q.mode='combat';const zd=ZN[S.zone.id-1],u=wildUnit(pick(zd.sp),clamp(S.P.lv,zd.lv[0],zd.lv[1]),0);u.temporary=true;u.noSeal=true;startBattle([u],'taleTrial',S.zone.id);B().noFlee=true;q.battleCheckpoint=JSON.parse(JSON.stringify(B()));}});};
WorldTales.finishAfter=function(){const q=this.session(),s=this.state(),a=s.aftermaths[q.pending.source],def=this.afterDef(a);a.repaired=true;a.method=q.pending.method;a.finishedAt=s.serial;s.effects=s.effects.filter(e=>!(e.source===a.source&&this.negative(e)));s.followupsSeen[a.zone]=true;q.result.push(def.outcome,'แก้ผลเสียของคำสัญญานี้แล้ว · ประวัติการเลือกเดิมยังถูกเก็บไว้');delete q.pending;q.mode='result';delete q.battleCheckpoint;};
const detailResolve=WorldTales.resolve;
WorldTales.resolve=function(){return this.session()?.pending?.kind==='aftermath'?this.finishAfter():detailResolve.call(this);};
WorldTales.rumor=function(){const s=this.state(),candidates=Object.values(s.aftermaths).filter(a=>!a.repaired&&a.heard<2&&s.serial>=a.at+a.heard);if(candidates.length){const a=pick(candidates),d=this.afterDef(a),text=d.hint[a.heard];a.heard++;s.rumors.push({text,source:a.source,stage:a.heard,at:s.serial});s.rumors=s.rumors.slice(-60);return text;}const text=pick(TALES_DATA.chatter);s.rumors.push({text,at:s.serial});s.rumors=s.rumors.slice(-60);return text;};
const detailNext=WorldTales.next;
WorldTales.next=function(token){const q=this.session(),r=q&&this.state().quests[q.followId];if(this.valid(token)&&q.mode==='follow'&&r?.kind!=='short'&&r.progress<r.targets.length-1){const d=this.data(r.id),target=r.targets[r.progress];return this.tx(()=>{const clue=d.clues?.[r.progress]||d.scene;r.progress++;q.mode='result';q.result=[clue.replace(String(target),ZN[target-1].n),'ตรวจร่องรอยแล้ว · จุดต่อไปคือ '+ZN[r.targets[r.progress]-1].n];});}return detailNext.call(this,token);};
const detailView=WorldTales.view;
WorldTales.view=function(){const q=this.session();if(q?.mode==='aftermath'){const a=this.state().aftermaths[q.source],d=this.afterDef(a),cost=60+ZN[a.zone-1].lv[0]*8;return '<section class="stack" id="worldTales"><small>ผลของคำสัญญาที่กลับมา</small><h2>'+esc(d.title)+'</h2>'+this.extraPanel(a.zone,1,d.scene)+'<p>'+esc(d.scene)+'</p><p class="sub">เคยเลือก: '+esc(a.title)+'</p><div class="tale-choices">'+this.cardButton(a.zone,4,1,d.help,'taleAfter',q.token+'|fund',S.P.gold<cost)+''+this.cardButton(a.zone,4,2,'ลงแรงคุ้มกันผู้ช่วยเหลือ','taleAfter',q.token+'|volunteer',S.P.mp<Math.ceil(pStats().mp*.15))+'<button class="btn full" data-a="taleAfter" data-v="'+q.token+'|later">รับฟังไว้ก่อน</button></div>'+Secret.status()+'</section>';}
 let html=detailView.call(this);if(q?.mode==='question'&&this.choiceData()?.kind!=='short')html=html.replace('</section>','<button class="btn full" data-a="taleDefer" data-v="'+q.token+'">ขอกลับไปหาข้อมูลก่อนตัดสินใจ</button></section>');if(q?.gearMenu!=null){const menu='<div class="card"><h3>เลือกอุปกรณ์</h3>'+this.donatable().map(x=>'<button class="btn full" data-a="taleGear" data-v="'+q.token+'|'+x.index+'">'+itemIcon(x.id,32)+esc(EQ[x.id].n)+'</button>').join('')+'</div>';html=html.replace('</section>',menu+'</section>');}return html;};
const detailLeave=WorldTales.leave;
WorldTales.leave=function(t){if(this.session()?.mode==='aftermath')return;return detailLeave.call(this,t);};
const detailJournal=WorldTales.journal;
WorldTales.journal=function(){const s=this.state();let html=detailJournal.call(this);const after='<h3>ผลกระทบที่ยังตามต่อได้</h3>'+Object.values(s.aftermaths).map(a=>{const d=this.afterDef(a);return '<details class="card"><summary>'+esc(d.title)+' · '+(a.repaired?'ช่วยแก้ผลแล้ว':a.heard?'มีเบาะแสแล้ว':'ยังมีข่าวที่รอฟัง')+'</summary>'+this.extraPanel(a.zone,a.repaired?2:1,d.title)+'<p>'+esc(a.repaired?d.outcome:a.heard?d.hint[a.heard-1]:'ชาวบ้านและผู้เดินทางอาจรู้เรื่องเพิ่มเติม')+'</p><small>ตามต่อใน '+esc(ZN[a.zone-1].n)+'</small>'+(!a.repaired&&a.heard&&S.zone?.id===a.zone&&!S.battle?'<button class="btn full" data-a="taleTrackAfter" data-v="'+esc(a.source)+'">ตามไปพบผู้เกี่ยวข้อง</button>':'')+'</details>';}).join('');html=html.replace('<h3>ข่าวที่เคยได้ยิน</h3>',after+'<h3>ข่าวที่เคยได้ยิน</h3>');for(const e of s.effects.filter(e=>e.kind!=='dragonAid'&&(e.charges>0||e.repairBound||TALE_EFFECT_KINDS.includes(e.kind))))if(!html.includes(esc(this.effectText(e)))&&(e.charges>0||e.repairBound||e.expiresSerial>=s.serial||e.until>=(s.visits[e.zone]||0)))html=html.replace('<h3>ข่าวที่เคยได้ยิน</h3>','<p class="card">'+esc(this.effectText(e))+'</p><h3>ข่าวที่เคยได้ยิน</h3>');return html;};
WorldTales.epilogues=function(snapshot){const s=this.state(),choices=snapshot||Object.values(s.consequences),afters=snapshot?(s.ending?.aftermaths||{}):s.aftermaths;return [7,1,2,3,4,5,6].map(zone=>{const secret=choices.find(c=>c.key==='secret:'+zone),special=choices.find(c=>c.key==='special:encounter-'+zone),long=choices.find(c=>c.key.startsWith('quest:')&&this.data(c.key.slice(6))?.kind==='long'&&c.zone===zone),helped=Object.values(afters).some(a=>a.zone===zone&&a.repaired),negative=(snapshot?s.ending?.effects||[]:s.effects).filter(e=>(e.homeZone||e.zone)===zone&&this.negative(e)),repaired=helped&&negative.every(e=>afters[e.source]?.repaired);let text;
 if(secret&&special){text=special.branch===2&&zone===3?(secret.branch===0?'แก่นพลังหล่อเลี้ยงค่ายผู้ลี้ภัย ประตูรองเปิดน้ำให้อสูรด้วย แต่เมืองเก่ายังมีแนวกำแพงถูกทรายกลืน':'แก่นยังป้องกันเมืองเก่า ประตูรองแบ่งน้ำให้คาราวาน ชาวบ้านต้องช่วยกันขนเสบียงผ่านเส้นทางไกล'):TALES_DATA.mixedEndings[zone][secret.branch*2+special.branch];}else if(secret||special)text=(secret||special).outcome;else{const old=SECRET_DATA.locations.find(d=>d.zone===zone),rec=old&&Secret.state().locations[old.id];text=rec?.completed?rec.outcome:'โลกในดินแดนนี้ยังดำเนินต่อ ผู้คนมีเรื่องที่คุณอาจกลับไปพบภายหลัง';}
 if(long)text+=' '+long.outcome;if(repaired)text+=' '+TALES_DATA.aftermaths.find(d=>d.zone===zone).ending;else if(helped)text+=' มีผู้ได้รับความช่วยเหลือเพิ่มเติม แต่ผลของอีกคำสัญญายังรอการรับผิดชอบ';
 const shorts=choices.filter(c=>c.zone===zone&&c.key.startsWith('quest:')&&this.data(c.key.slice(6))?.kind==='short');if(!secret&&!special&&!long&&shorts.length)text=shorts.slice(0,2).map(c=>c.outcome).join(' ');
 return {zone,title:ZN[zone-1].n,text,repaired};});};
const detailEndBattle=endBattle;
endBattle=function(res){const b=B(),out=detailEndBattle(res);if(res==='win'&&b?.kind==='boss'&&Number(b.meta)===6&&S.P.cleared){const s=WorldTales.state();s.ending.aftermaths=JSON.parse(JSON.stringify(s.aftermaths));s.ending.effects=JSON.parse(JSON.stringify(s.effects));s.ending.network=Object.values(s.quests).filter(r=>r.kind==='long'&&r.status==='completed').map(r=>r.id);s.ending.special=Secret.canEnding();save();}return out;};
const detailCinema=cinemaView;
cinemaView=function(intro=false){const html=detailCinema(intro),q=S.ui.cinema,f=q&&storyFrames(q.chapter,q.after)[q.index],e=f?.taleZone&&WorldTales.epilogues(WorldTales.state().ending?.choices).find(e=>e.zone===f.taleZone);return e?.repaired?html.replace(/<figure class="tale-panel"[^>]*><\/figure>/,WorldTales.extraPanel(e.zone,2,e.title)):html;};

Object.assign(handlers,{
 taleAfter:v=>{const [t,m]=v.split('|');WorldTales.helpAfter(t,m);},
 taleGear:v=>{const [t,n]=v.split('|');if(!WorldTales.valid(t))return;const x=WorldTales.donatable().find(x=>x.index===Number(n));if(!x)return;const i=WorldTales.session().gearMenu;WorldTales.session().gearChoice=x;delete WorldTales.session().gearMenu;WorldTales.request(t,i);},
 taleTrackAfter:key=>{if(S.battle||WorldTales.session()||S.zone?.secretSession||S.zone?.specialSession||S.zone?.riddleSession||S.zone?.warpGate)return;const a=WorldTales.state().aftermaths[key];if(!a||!a.heard||a.repaired||WorldTales.state().serial<a.availableAfter)return;if(S.zone.ev||!S.zone.fork)return toast('เดินต่อถึงทางแยกก่อนตามข่าว');delete S.ui.taleBook;WorldTales.startAfter(key,false);},
 taleListen:()=>{if(!S.P||S.battle&&!S.battle.over||WorldTales.session())return;WorldTales.tx(()=>{S.ui.taleTalk={text:WorldTales.rumor(),back:S.screen,zone:S.zone?.id||7};S.screen='story';});},
 taleTalkBack:()=>{const back=S.ui.taleTalk?.back;delete S.ui.taleTalk;S.screen=back||'town';render();}
});
const detailTown=vTown;vTown=function(){return detailTown()+'<button class="btn full" data-a="taleListen">คุยกับผู้เดินทาง · ข่าวลือ</button>';};
const detailZone=vZone;vZone=function(){const html=detailZone();return S.zone?.ev?.type==='village'&&!WorldTales.session()?html+'<button class="btn full" data-a="taleListen">ฟังเรื่องจากคนพักในหมู่บ้าน</button>':html;};
const detailStory=vStory;vStory=function(){const q=S.ui.taleTalk;return q?'<section class="stack" id="worldTales"><h2>เสียงจากผู้เดินทาง</h2>'+WorldTales.panel(q.zone,0,0,'ผู้เดินทางข้างกองไฟ')+'<p>'+esc(q.text)+'</p><button class="btn full" data-a="taleTalkBack">ขอบคุณสำหรับเรื่องเล่า</button></section>':detailStory();};

function taleRecoveryAmount(it,key){return Math.max(0,Math.round((it[key]||0)*(1+(S.zone?WorldTales.modifier(key==='hp'?'potionHP':'potionMP'):0))));}
WorldTales.adjustStats=function(st){if(!S.zone||typeof WORLD!=='undefined'&&WORLD.room?.status==='active'||typeof PVP!=='undefined'&&PVP.room?.status==='active')return st;return {...st,mp:Math.max(1,Math.round(st.mp*(1+this.modifier('maxMP'))))};};
WorldTales.skillFactor=function(u){return S.zone&&u.side==='ally'&&u.kind==='player'&&!isWorldBattle()?1+this.modifier('mpCost'):1;};
WorldTales.hospitalFactor=function(){return 1+this.modifier('hospital');};
for(const key of ['heal','zheal']){const old=handlers[key];handlers[key]=function(...a){const before=S.P.gold,effects=WorldTales.active('hospital'),out=old(...a);if(S.P.gold<before){for(const e of effects)if(e.charges>0)e.charges--;save();}return out;};}
const detailTrap=trap;trap=function(){const team=[S.P,...party()],hp=team.map(o=>o.hp),out=detailTrap(),rate=WorldTales.modifier('trap');if(rate){team.forEach((o,i)=>{if(hp[i]>0)o.hp=Math.max(1,hp[i]-Math.round((hp[i]-o.hp)*(1+rate)));});const message=out+' · ผลคำสัญญาปรับความเสียหายกับดัก '+Math.round(rate*100)+'%';if(S.ui.trapNotice)S.ui.trapNotice.message=message;return message;}return out;};
const detailHit=hitOne;hitOne=function(u,sk,...a){const oldA=TALE_RUNTIME.attacker,oldE=TALE_RUNTIME.element;TALE_RUNTIME.attacker=u;TALE_RUNTIME.element=sk.el;try{return detailHit(u,sk,...a);}finally{TALE_RUNTIME.attacker=oldA;TALE_RUNTIME.element=oldE;}};
const detailHurt=hurt;hurt=function(u,d,...a){if(WorldTales.offline()&&u.side==='ally'){const base=WorldTales.modifier('guard'),boss=TALE_RUNTIME.attacker?.boss?WorldTales.modifier('bossGuard'):0,el=WorldTales.modifier('elementGuard',TALE_RUNTIME.element?[TALE_RUNTIME.element]:[]),shield=(B().protectorShield||TALE_RUNTIME.pendingProtector)&&B().round<=2?.15:0,total=clamp(base+boss+el+shield,-.25,.25);d=Math.round(d*(1-total)/(1-base));}return detailHurt(u,d,...a);};
const detailGain=gainExp;gainExp=function(o,n,isP){return detailGain(o,Math.round(n*(!isP&&WorldTales.offline()?1+WorldTales.modifier('petXP'):1)),isP);};
