const detailForkChoice=chooseFork;chooseFork=function(i){const door=S.zone?.fork?.[Number(i)];if(door&&door.k==='beast'&&!door.h&&!WorldTales.session()&&WorldTales.modifier('encounter')<0&&Math.random()<-WorldTales.modifier('encounter')){S.zone.depth++;S.zone.fork=null;S.zone.ev={type:'spring',msg:'แผนผังที่ได้รับพาผ่านเส้นทางเลี่ยงอสูร คุณได้พักโดยไม่ต้องต่อสู้'};save();render();return;}return detailForkChoice(i);};

