function stageSevenAtlas(w,h,xs,ys,row,col){const x=xs[col]+2,y=ys[row]+2,cw=xs[col+1]-x-2,ch=ys[row+1]-y-2;return '--crop-size:'+w/cw*100+'% '+h/ch*100+'%;--crop-position:'+x/(w-cw)*100+'% '+y/(h-ch)*100+'%;--crop-ratio:'+cw/ch+';--crop-width:512px';}
function stageSevenCrop(cols,rows,row,col,ratio){return '--crop-size:'+cols*100+'% '+rows*100+'%;--crop-position:'+(cols===1?0:col*100/(cols-1))+'% '+(rows===1?0:row*100/(rows-1))+'%;--crop-ratio:'+ratio+';--crop-width:512px';}
const ironTalePanel=WorldTales.panel;WorldTales.panel=function(zone,row,col,label){if(zone!==8)return ironTalePanel.call(this,zone,row,col,label);return '<figure class="tale-panel" role="img" aria-label="'+esc(label)+'" style="--tale-art:url(assets/ui/stage7/quests.png);'+stageSevenAtlas(1024,1536,[0,341,683,1024],[0,225,442,662,926,1208,1536],row,col)+'"></figure>';};
