function stageSevenFirstEligible(){return !!S.P&&(S.P.forestClears?.[8]||0)>0&&!S.P.stageSevenFirstReward;}
function stageSevenRewardPanel(){if(!stageSevenFirstEligible())return '';return '<section class="card stack"><h2>รางวัลผ่านด่าน 7 ครั้งแรก</h2><p>เลือกหนึ่งอย่าง รับได้ครั้งเดียว แยกจากสิทธิ์สถานที่ลับ</p><div class="secret-choice-grid"><button class="btn" data-a="stageSevenFirstReward" data-v="gear">'+Secret.panel(stageSevenSecret,3,'อุปกรณ์ตำนานสุริยคราส 1 ชิ้น')+'</button><button class="btn" data-a="stageSevenFirstReward" data-v="pet">'+Secret.panel(stageSevenSecret,4,'อสูรตำนาน Lv60 1 ตัว')+'</button></div><small>สุ่มภายในหมวดที่เลือก อาวุธตรงสายอาชีพ อสูรไม่รวมตำนานสุริยคราส</small></section>';}
let stageSevenClaimBusy=false;handlers.stageSevenFirstReward=function(choice){if(stageSevenClaimBusy||!stageSevenFirstEligible()||S.battle&&!S.battle.over||!['gear','pet'].includes(choice))return;stageSevenClaimBusy=true;const before=JSON.stringify(S);try{let id,label;if(choice==='gear'){const pool=Object.keys(EQ).filter(k=>EQ[k].worldLegend&&(EQ[k].slot!=='weapon'||EQ[k].wt===clsWeapon(S.P.cls)));id=pick(pool);if(!id)throw Error('empty reward');S.P.owned.push(id);S.P.legend||={};S.P.legend[id]=1;label=EQ[id].n;}else{normalizePack();const pool=Object.keys(SP).filter(k=>SP[k].legendary&&!SP[k].solar&&!SP[k].noseal);id=pick(pool);const pet=mkPet(id,60);S.P.pets.push(pet);if(S.P.carried.length<carryLimit())S.P.carried.push(pet.uid);S.P.seen[id]=1;S.P.caught[id]=1;markFormSeen(id,pet.form||0);label=SP[id].n+' Lv60';}S.P.stageSevenFirstReward={choice,id,label,claimedAt:Date.now()};Secret.persist();save();render();toast('รางวัลผ่านด่าน 7 ครั้งแรก: '+label);}catch(e){S=JSON.parse(before);toast('บันทึกรางวัลไม่ได้ ยังไม่ใช้สิทธิ์ กรุณาลองอีกครั้ง');}finally{stageSevenClaimBusy=false;}};
const stageSevenRewardBattle=vBattle;vBattle=function(){return (B()?.over?stageSevenRewardPanel():'')+stageSevenRewardBattle();};
const stageSevenRewardTown=vTown;vTown=function(){return stageSevenRewardPanel()+stageSevenRewardTown();};
